import{_ as a,o as i,c as o,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Tailoring","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/tailoring.md","filePath":"es/guide/professions/tailoring.md"}'),s={name:"es/guide/professions/tailoring.md"};function n(l,e,t,c,d,p){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="tailoring" tabindex="-1">Tailoring <a class="header-anchor" href="#tailoring" aria-label="Enlace permanente a &quot;Tailoring&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Esta página describe el rediseño previsto, no mecánicas confirmadas en juego. <strong>Implementación/disponibilidad:</strong> no establecidas para este rediseño. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-08 respecto a la <a href="/Syrolands-Public/es/game-design/professions/tailoring.html">especificación completa del diseño</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Tailoring trabaja cuero, tela, fibras y protección flexible.</li><li>Ajustes, costuras, reparación y evaluación le dan valor sobre el terreno más allá de producir ropa.</li><li>Materiales, moda y métodos aprendidos apoyan la especialización; la recolección y las capas siguen en estado Propuesto.</li></ul><h2 id="what-it-does" tabindex="-1">Qué hace <a class="header-anchor" href="#what-it-does" aria-label="Enlace permanente a &quot;Qué hace&quot;">​</a></h2><p>Tailoring es el oficio de los materiales flexibles: cuero, pieles, tela, fibras, acolchado, hilo, prendas y armaduras flexibles. Recolección, conservación, procesamiento, clasificación, corte, montaje, ajuste y acabado deberían tener cada uno un propósito significativo.</p><h2 id="why-take-it-into-the-field" tabindex="-1">¿Por qué llevarla al terreno? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Enlace permanente a &quot;¿Por qué llevarla al terreno?&quot;">​</a></h2><p>Los ajustes, las costuras de campaña, las reparaciones y la evaluación de materiales la hacen útil más allá de producir ropa. El ajuste y mantenimiento correctos deberían reducir las penalizaciones pertinentes sin convertirse en una bonificación fija de armadura. El cuero y la tela pueden proteger de formas distintas a las placas.</p><h2 id="learning-and-specialization" tabindex="-1">Aprendizaje y especialización <a class="header-anchor" href="#learning-and-specialization" aria-label="Enlace permanente a &quot;Aprendizaje y especialización&quot;">​</a></h2><p>El Material/Tailoring Journal puede incluir zonas de piel, tratamientos y conocimiento de construcción. El daño a una criatura puede afectar a las pieles recolectadas. Anatomy y Animal Lore se proponen como compañeras en la recolección; una habilidad independiente de desuello no está decidida. La moda también es una vía legítima: cortes, tintes, bordados y estilos culturales o de gremios pueden transmitir identidad y estatus.</p><h2 id="progression-and-related-crafts" tabindex="-1">Progresión y oficios relacionados <a class="header-anchor" href="#progression-and-related-crafts" aria-label="Enlace permanente a &quot;Progresión y oficios relacionados&quot;">​</a></h2><p>Se aplican el <a href="/Syrolands-Public/es/guide/professions/overview.html">aprendizaje y la producción compartidos</a>, con trabajo de materiales más avanzado al crecer la habilidad y el conocimiento. <a href="/Syrolands-Public/es/guide/professions/alchemy.html">Alchemy</a> puede aportar tratamientos, pigmentos y mordientes; la <a href="/Syrolands-Public/es/guide/professions/carpentry.html#bowmaking-and-fletching">vía Bowmaking de Carpentry</a> puede usar apoyo opcional de sastrería. Las reglas de recolección, ajuste y capas siguen siendo propuestas.</p><p><a href="/Syrolands-Public/es/guide/professions/overview.html">Todas las profesiones</a> · <a href="/Syrolands-Public/es/game-design/professions/tailoring.html">Especificación completa del diseño</a></p>',13)])])}const h=a(s,[["render",n]]);export{m as __pageData,h as default};
